#!/usr/bin/env node
/**
 * C8 (2026-11-10): generate src/lib/backend/function-refs.ts from the runtime
 * registry so `api.*` call sites are checked against the actual function
 * surface at typecheck time. Internal handlers are included in the type union
 * (they are rejected at the HTTP boundary regardless); the generated file is
 * committed and regenerated by hand when functions change.
 *
 * Usage: node --import ./scripts/register-ts-transpile.mjs scripts/gen-function-refs.mjs [--check]
 *   --check   exit 1 if the committed file is stale (used by CI/gates)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const { describeFunctions } = await import("../src/lib/backend/runtime.ts");

const byModule = new Map();
for (const { key: ref } of describeFunctions()) {
  const idx = ref.indexOf(":");
  const module = ref.slice(0, idx).replace(/\//g, "_");
  const fn = ref.slice(idx + 1);
  if (!fn || fn.startsWith("_")) continue; // registry-testing helpers are not client surface
  if (!byModule.has(module)) byModule.set(module, new Set());
  byModule.get(module).add(fn);
}
for (const fns of byModule.values()) {
  // deterministic output ordering
}
const modules = [...byModule.entries()].sort(([a], [b]) => a.localeCompare(b));

let out = `// GENERATED by scripts/gen-function-refs.mjs — do not edit by hand.
// Regenerate after adding/renaming backend functions:
//   node --import ./scripts/register-ts-transpile.mjs scripts/gen-function-refs.mjs
import type { FunctionRef } from "./api";

export type ApiSurface = {
`;
for (const [module, fns] of modules) {
  out += `  "${module}": {\n`;
  for (const fn of [...fns].sort()) {
    out += `    ${fn}: FunctionRef;\n`;
  }
  out += `  };\n`;
}
out += `};\n`;

const target = resolve(root, "src/lib/backend/function-refs.ts");
if (process.argv.includes("--check")) {
  const current = readFileSync(target, "utf8");
  if (current !== out) {
    console.error("FAIL: src/lib/backend/function-refs.ts is stale — rerun scripts/gen-function-refs.mjs");
    process.exit(1);
  }
  console.log("✔ function-refs.ts is up to date");
  process.exit(0);
}
writeFileSync(target, out);
console.log(`✔ wrote ${target} (${modules.length} modules)`);
